1	/**
2	 * 多签钱包策略引擎。
3	 *
4	 * 在阈值策略、签名收集、重放防护、FIFO 执行队列、策略变更任务与任务取消之上，新增
5	 * “原子批量普通交易”：当前所有者以阈值签名（safe-wallet/tx-batch/v1 域，绑定钱包标识、
6	 * nonce、截止时间与按顺序编码的全部调用）提交一个有序调用列表（1..64 项）。
7	 * 批量任务只入队一个队列任务、只消费一个 nonce；执行时整批成功产生一个 transfer-batch
8	 * 回执（不产生部分执行回执），失败则整批不生效。批量任务沿用同一 FIFO 队列、取消语义与
9	 * 终态幂等；单笔交易 / 策略变更 / 取消签名均不能授权批量交易。
10	 *
11	 * 在此之上新增“普通交易分阶段审批”：createTransactionApproval 登记交易（不消费 nonce、
12	 * 不建任务），addApprovalSignature 逐个收集当前所有者签名（safe-wallet/tx-approval/v1 域，
13	 * 绑定创建时策略版本与完整交易字段），达到创建时确认数后由 submitApprovedTransaction 按
14	 * 既有 safe-wallet/tx/v1 摘要入队并只消费创建时 nonce。审批与直接提交的签名摘要互不通用。
15	 *
16	 * 再新增“策略变更分阶段审批”：createPolicyApproval 登记一次目标策略变更（绑定版本、nonce、
17	 * deadline、新所有者顺序与新确认数，不消费 nonce、不建任务、不改策略），
18	 * addPolicyApprovalSignature 逐个收集当前所有者签名（safe-wallet/policy-change-approval/v1
19	 * 域），达到创建时确认数后由 submitApprovedPolicyChange 按既有 safe-wallet/policy-change/v1
20	 * 摘要入队一个 policy-change 任务并只消费创建时 nonce。同一 nonce 可登记多个候选审批，
21	 * 登记/加签均不改策略、不耗 nonce、不动队列；提交后执行时若版本已漂移，仍按既有
22	 * PolicyConflict 失败终态处理，不改策略。
23	 *
24	 * 再新增“批量交易分阶段审批”：createBatchApproval 登记一个有序调用列表（绑定版本、nonce、
25	 * deadline 与 1..64 项 calls，不消费 nonce、不建任务、不改策略），addBatchApprovalSignature
26	 * 逐个收集当前所有者签名（safe-wallet/tx-batch-approval/v1 域，绑定钱包标识、版本、nonce、
27	 * deadline 与按顺序编码的全部调用），达到创建时确认数后由 submitBatchApproval 按既有
28	 * safe-wallet/tx-batch/v1 摘要入队一个 transaction-batch 任务并只消费创建时 nonce。
29	 * 审批签名与批量直接提交签名互不通用；执行保持原子回执、FIFO、取消与终态幂等。
30	 */
31	
32	import {
33	  type Address,
34	  ZERO_ADDRESS,
35	  isZeroAddress,
36	  normalizeAddress,
37	  recoverAddress,
38	} from './crypto.ts';
39	import {
40	  hashCancellation,
41	  hashBatchApproval,
42	  hashPolicyChange,
43	  hashPolicyApproval,
44	  hashTransaction,
45	  hashTransactionApproval,
46	  hashTransactionBatch,
47	  type PolicyApprovalRequest,
48	  type PolicyChangeRequest,
49	  type TransactionApprovalRequest,
50	  type TransactionBatchApprovalRequest,
51	  type TransactionBatchRequest,
52	  type TransactionRequest,
53	} from './encoding.ts';
54	import {
55	  ApprovalAlreadySubmittedError,
56	  ApprovalExpiredError,
57	  ApprovalNonceConflictError,
58	  ApprovalNotFoundError,
59	  ApprovalPolicyConflictError,
60	  ApprovalThresholdNotMetError,
61	  DuplicateApprovalSignatureError,
62	  InvalidApprovalSignatureError,
63	  InvalidCancellation,
64	  InvalidPolicyChange,
65	  InvalidTransaction,
66	  InvalidTransactionBatch,
67	  NonceAlreadyUsedError,
68	  RequestExpired,
69	  PolicyConflict,
70	  InvalidQueueStateError,
71	  TaskCancellationConflict,
72	  TaskNotFoundError,
73	} from './errors.ts';
74	import { ExecutionQueue, type QueueTask } from './queue.ts';
75	import { createHash } from 'node:crypto';
76	
77	// ---------- 任务载荷 ----------
78	
79	export type WalletTaskPayload =
80	  | {
81	      kind: 'transaction';
82	      deadline: bigint;
83	      to: Address;
84	      value: bigint;
85	      data: Uint8Array;
86	    }
87	  | {
88	      kind: 'transaction-batch';
89	      deadline: bigint;
90	      /** 有序调用；顺序即执行顺序，执行回执按同一顺序给出 */
91	      calls: BatchCall[];
92	    }
93	  | {
94	      kind: 'policy-change';
95	      deadline: bigint;
96	      /** 提交时绑定的策略版本；执行时必须仍等于当前版本 */
97	      version: bigint;
98	      newOwners: Address[];
99	      newConfirmations: bigint;
100	    };
101	
102	/** 批量任务内的单次调用（规范化后的收款地址、原金额、原始 data 副本） */
103	export interface BatchCall {
104	  to: Address;
105	  value: bigint;
106	  data: Uint8Array;
107	}
108	
109	export type WalletTask = QueueTask<WalletTaskPayload>;
110	
111	export interface PolicyState {
112	  owners: Address[];
113	  confirmations: bigint;
114	  version: bigint;
115	}
116	
117	export interface WalletOptions {
118	  id: string;
119	  owners: Address[];
120	  confirmations: bigint | number;
121	  /** 注入时钟，返回 Unix 秒；默认取系统时间 */
122	  now?: () => bigint;
123	}
124	
125	export interface TransactionSubmission {
126	  nonce: bigint | number;
127	  deadline: bigint | number;
128	  to: string;
129	  value: bigint | number;
130	  data?: Uint8Array;
131	}
132	
133	export interface PolicyChangeSubmission {
134	  version: bigint | number;
135	  nonce: bigint | number;
136	  deadline: bigint | number;
137	  newOwners: string[];
138	  newConfirmations: bigint | number;
139	}
140	
141	export interface CancellationSubmission {
142	  /** 目标任务 id（队列快照中的任务标识） */
143	  taskId: string;
144	  nonce: bigint | number;
145	  deadline: bigint | number;
146	}
147	
148	/** 批量提交中的单次调用（原始输入；地址在校验时规范化） */
149	export interface BatchCallSubmission {
150	  to: string;
151	  value: bigint | number;
152	  /** 必含的调用数据（允许零长度）；必须是 Uint8Array */
153	  data: Uint8Array;
154	}
155	
156	export interface BatchTransactionSubmission {
157	  nonce: bigint | number;
158	  deadline: bigint | number;
159	  /** 有序调用列表：非空且最多 MAX_BATCH_CALLS 项，顺序参与签名且不得改变 */
160	  calls: readonly BatchCallSubmission[];
161	}
162	
163	/** 批量交易调用数量上限（含） */
164	export const MAX_BATCH_CALLS = 64;
165	
166	// ---------- 普通交易分阶段审批 ----------
167	
168	/** 审批生命周期：collecting → ready → submitted；expired / conflicted 为查询派生状态 */
169	export type ApprovalStatus = 'collecting' | 'ready' | 'expired' | 'conflicted' | 'submitted';
170	
171	/** 审批的公开快照（创建 / 加签 / 查询时返回） */
172	export interface TransactionApproval {
173	  /** 审批标识（由创建序号与审批摘要派生，引擎内唯一） */
174	  id: string;
175	  /** 审批签名摘要（hex，safe-wallet/tx-approval/v1 域） */
176	  digest: string;
177	  /** 创建时绑定的策略版本 */
178	  version: bigint;
179	  /** 创建时绑定的确认数（阈值） */
180	  confirmations: bigint;
181	  /** 已收集签名者（按加签顺序，去重） */
182	  signers: Address[];
183	  status: ApprovalStatus;
184	}
185	
186	/** 审批的内部记录：完整交易字段 + 签名收集状态 */
187	interface ApprovalRecord {
188	  id: string;
189	  digest: Buffer;
190	  version: bigint;
191	  confirmations: bigint;
192	  nonce: bigint;
193	  deadline: bigint;
194	  to: Address;
195	  value: bigint;
196	  data: Buffer;
197	  /** 按加签顺序的签名者（与 signatures 的键一一对应） */
198	  signers: Address[];
199	  signatures: Map<Address, Buffer>;
200	  submitted: boolean;
201	}
202	
203	// ---------- 策略变更分阶段审批 ----------
204	
205	/** 策略变更审批的公开快照（创建 / 加签 / 查询时返回） */
206	export interface PolicyApproval {
207	  /** 审批标识（由创建序号与审批摘要派生，引擎内唯一） */
208	  id: string;
209	  /** 审批签名摘要（hex，safe-wallet/policy-change-approval/v1 域） */
210	  digest: string;
211	  /** 创建时绑定的策略版本 */
212	  version: bigint;
213	  /** 创建时绑定的确认数（阈值） */
214	  confirmations: bigint;
215	  /** 创建时绑定的 nonce（提交时才消费） */
216	  nonce: bigint;
217	  deadline: bigint;
218	  /** 目标新所有者（按创建时给定顺序；顺序参与签名） */
219	  newOwners: Address[];
220	  newConfirmations: bigint;
221	  /** 已收集签名者（按加签顺序，去重） */
222	  signers: Address[];
223	  status: ApprovalStatus;
224	}
225	
226	/** 策略变更审批的内部记录：目标策略字段 + 版本/nonce 绑定 + 签名收集状态 */
227	interface PolicyApprovalRecord {
228	  id: string;
229	  digest: Buffer;
230	  version: bigint;
231	  confirmations: bigint;
232	  nonce: bigint;
233	  deadline: bigint;
234	  newOwners: Address[];
235	  newConfirmations: bigint;
236	  /** 按加签顺序的签名者（与 signatures 的键一一对应） */
237	  signers: Address[];
238	  signatures: Map<Address, Buffer>;
239	  submitted: boolean;
240	}
241	
242	// ---------- 批量交易分阶段审批 ----------
243	
244	/** 批量交易审批的公开快照（创建 / 加签 / 查询 / 列表时返回） */
245	export interface BatchApproval {
246	  /** 审批标识（由创建序号与审批摘要派生，引擎内唯一） */
247	  id: string;
248	  /** 审批签名摘要（hex，safe-wallet/tx-batch-approval/v1 域） */
249	  digest: string;
250	  /** 创建时绑定的策略版本 */
251	  version: bigint;
252	  /** 创建时绑定的确认数（阈值） */
253	  confirmations: bigint;
254	  /** 创建时绑定的 nonce（提交时才消费） */
255	  nonce: bigint;
256	  deadline: bigint;
257	  /** 有序调用列表（按创建时给定顺序；顺序参与签名） */
258	  calls: BatchCall[];
259	  /** 已收集签名者（按加签顺序，去重） */
260	  signers: Address[];
261	  status: ApprovalStatus;
262	}
263	
264	/** 批量交易审批的内部记录：有序调用 + 版本/nonce 绑定 + 签名收集状态 */
265	interface BatchApprovalRecord {
266	  id: string;
267	  digest: Buffer;
268	  version: bigint;
269	  confirmations: bigint;
270	  nonce: bigint;
271	  deadline: bigint;
272	  /** 有序调用（规范化后的收款地址、原金额、原始 data 副本） */
273	  calls: BatchCall[];
274	  /** 按加签顺序的签名者（与 signatures 的键一一对应） */
275	  signers: Address[];
276	  signatures: Map<Address, Buffer>;
277	  submitted: boolean;
278	}
279	
280	function isNonNegativeInteger(n: bigint, maxBits = 256): boolean {
281	  return n >= 0n && n < 2n ** BigInt(maxBits);
282	}
283	
284	/** 安全标量转换：非法输入（undefined / 字符串等）归一为指定的 Invalid* 错误 */
285	function toBigInt(value: unknown, Invalid: new (msg: string) => Error, field: string): bigint {
286	  if (typeof value === 'bigint') return value;
287	  if (typeof value === 'number' && Number.isSafeInteger(value)) return BigInt(value);
288	  if (typeof value === 'string' && /^\d+$/.test(value.trim())) return BigInt(value.trim());
289	  throw new Invalid(`field "${field}" must be a non-negative integer`);
290	}
291	
292	export class MultiSigWallet {
293	  readonly id: string;
294	  private readonly now: () => bigint;
295	
296	  private owners: Address[];
297	  private readonly ownerSet: Set<Address>;
298	  private confirmations: bigint;
299	  private version: bigint;
300	
301	  /** 下一个期望 nonce（严格递增，顺序提交） */
302	  private nextNonce = 0n;
303	  /** 已消费 nonce（入队即消费；失败终态也不释放） */
304	  private readonly usedNonces = new Set<bigint>();
305	
