320	  constructor(opts: WalletOptions) {
321	    const owners = normalizeOwnerList(opts.owners);
322	    const confirmations = BigInt(opts.confirmations);
323	    if (confirmations <= 0n || confirmations > BigInt(owners.length)) {
324	      throw new InvalidPolicyChange(
325	        `initial confirmations must be within 1..owners (${owners.length}), got ${confirmations}`,
326	      );
327	    }
328	    this.id = opts.id;
329	    this.now = opts.now ?? (() => BigInt(Math.floor(Date.now() / 1000)));
330	    this.owners = owners;
331	    this.ownerSet = new Set(owners);
332	    this.confirmations = confirmations;
333	    this.version = 1n;
334	    this.queue = new ExecutionQueue((task) => this.applyTask(task));
335	  }
