433	  // ---------- 任务取消 ----------
434	
435	  /**
436	   * 取消一个尚未执行的 queued 任务。
437	   *
438	   * 取消摘要使用 safe-wallet/cancel/v1 域标签，绑定钱包标识、目标任务 digest、nonce 与
439	   * 截止时间：签名无法改绑其他任务、其他钱包或其他时间窗口。
440	   *
441	   * 校验顺序（任一失败都不改变任务、不消费 nonce、不改变策略）：
442	   *   1) 字段非法 → InvalidCancellation
443	   *   2) nonce 复用 → NonceAlreadyUsedError（旧请求重放恒得此异常，即使已过期）
444	   *   3) deadline 早于当前时间 → RequestExpired
445	   *   4) nonce 顺序（须等于 expectedNonce）→ InvalidCancellation
446	   *   5) 目标不存在 → TaskNotFoundError；目标已终态 → TaskCancellationConflict
447	   *   6) 阈值签名（当前所有者、去重后达到当前确认数）→ InvalidCancellation
448	   *
449	   * 成功时目标任务由 queued 进入 cancelled 终态并返回：保留原 payload/digest/nonce，
450	   * 记录取消时间与取消摘要；不执行目标效果，不改变 owners/确认数/策略版本，
451	   * 只消费本次 nonce 并推进 expectedNonce。取消不要求任务在队首，也不调整队列顺序。
452	   */
453	  cancelTask(
454	    taskId: string,
455	    nonce: bigint | number,
456	    deadline: bigint | number,
457	    signatures: readonly Uint8Array[],
458	  ): WalletTask;
459	  cancelTask(sub: CancellationSubmission, signatures: readonly Uint8Array[]): WalletTask;
460	  cancelTask(
461	    a: string | CancellationSubmission,
462	    b: readonly Uint8Array[] | bigint | number,
463	    c?: bigint | number,
464	    d?: readonly Uint8Array[],
465	  ): WalletTask {
466	    const sub: CancellationSubmission =
467	      typeof a === 'string' || a === undefined || a === null
468	        ? { taskId: a as string, nonce: b as bigint | number, deadline: c as bigint | number }
469	        : a;
470	    const signatures: readonly Uint8Array[] =
471	      (typeof a === 'string' || a === undefined || a === null ? d : (b as readonly Uint8Array[])) ??
472	      ([] as readonly Uint8Array[]);
473	
474	    // (1) 字段安全转换（畸形输入只抛 InvalidCancellation）
475	    const nonce = toBigInt(sub.nonce, InvalidCancellation, 'nonce');
476	    if (!isNonNegativeInteger(nonce)) {
477	      throw new InvalidCancellation('nonce must be a non-negative integer');
478	    }
479	    // (2) nonce 复用优先于过期判定
480	    if (this.usedNonces.has(nonce)) throw new NonceAlreadyUsedError(nonce);
481	
482	    const deadline = toBigInt(sub.deadline, InvalidCancellation, 'deadline');
483	    if (!isNonNegativeInteger(deadline)) throw new InvalidCancellation('deadline out of range');
484	    // (3) 截止时间
485	    if (deadline < this.now()) {
486	      throw new RequestExpired(`request deadline ${deadline} already passed`);
487	    }
488	    // (4) nonce 顺序：取消与提交共用同一严格递增序列
489	    if (nonce !== this.nextNonce) {
490	      throw new InvalidCancellation(`expected nonce ${this.nextNonce}, got ${nonce}`);
491	    }
492	
493	    // (5) 目标任务状态
494	    const taskId = sub.taskId;
495	    if (typeof taskId !== 'string' || taskId.length === 0) {
496	      throw new InvalidCancellation('taskId must be a non-empty string');
497	    }
498	    const target = this.queue.getTask(taskId);
499	    if (target === null) throw new TaskNotFoundError(`task not found: ${taskId}`);
500	    if (target.status !== 'queued') {
501	      throw new TaskCancellationConflict(`task ${taskId} is already ${target.status}`);
502	    }
503	
504	    // (6) 阈值签名：摘要绑定钱包标识、目标任务 digest、nonce、deadline
505	    const digest = hashCancellation({
506	      walletId: this.id,
507	      taskDigest: target.digest,
508	      nonce,
509	      deadline,
510	    });
511	    this.verifyThresholdSignatures(digest, signatures, InvalidCancellation);
512	
513	    // 原子生效：目标任务进入 cancelled 终态 + 消费 nonce；策略与队列顺序不变
514	    const cancelled = this.queue.cancel(taskId, this.now(), digest.toString('hex'));
515	    this.usedNonces.add(nonce);
516	    this.nextNonce = nonce + 1n;
517	    return cancelled;
518	  }
