520	  // ---------- 普通交易分阶段审批（签名收集与提交分离；旧入口行为不变） ----------
521	
522	  /**
523	   * 创建一笔普通交易的分阶段审批：只校验并登记，不消费 nonce、不建任务、不改策略。
524	   *
525	   * 审批摘要用 safe-wallet/tx-approval/v1 域，绑定钱包标识、创建时策略版本与完整交易字段
526	   * （data 复制保存），与直接提交的 safe-wallet/tx/v1 摘要互不通用。
527	   *
528	   * 校验顺序与 submitTransaction 一致（失败不产生任何状态变化）：
529	   *   1) nonce 复用 → NonceAlreadyUsedError
530	   *   2) deadline 早于当前时间 → RequestExpired
531	   *   3) 字段非法或 nonce 跳号（须等于 expectedNonce）→ InvalidTransaction
532	   *
533	   * 成功时返回审批快照（标识、摘要、版本、确认数、空签名者列表、collecting 状态）。
534	   */
535	  createTransactionApproval(sub: TransactionSubmission): TransactionApproval {
536	    // (1) nonce 安全转换与复用判定（复用优先于过期，与既有提交一致）
537	    const nonce = toBigInt(sub.nonce, InvalidTransaction, 'nonce');
538	    if (!isNonNegativeInteger(nonce)) throw new InvalidTransaction('nonce must be a non-negative integer');
539	    if (this.usedNonces.has(nonce)) throw new NonceAlreadyUsedError(nonce);
540	
541	    // (2) 截止时间
542	    const deadline = toBigInt(sub.deadline, InvalidTransaction, 'deadline');
543	    if (!isNonNegativeInteger(deadline)) throw new InvalidTransaction('deadline out of range');
544	    if (deadline < this.now()) {
545	      throw new RequestExpired(`request deadline ${deadline} already passed`);
546	    }
547	    // (3) nonce 顺序：创建只登记不消费，但仍须绑定当前期望 nonce（跳号即非法）
548	    if (nonce !== this.nextNonce) {
549	      throw new InvalidTransaction(`expected nonce ${this.nextNonce}, got ${nonce}`);
550	    }
551	
552	    // (4) 交易字段校验与规范化（与直接提交同一套规则）
553	    const to = normalizeAddress(sub.to);
554	    if (to === null || isZeroAddress(to)) throw new InvalidTransaction('invalid or zero recipient address');
555	    const value = toBigInt(sub.value, InvalidTransaction, 'value');
556	    if (!isNonNegativeInteger(value)) throw new InvalidTransaction('value out of range');
557	    const dataField = sub.data;
558	    if (dataField !== undefined && !(dataField instanceof Uint8Array) && !ArrayBuffer.isView(dataField)) {
559	      throw new InvalidTransaction('data must be a byte array');
560	    }
561	    // 复制一份，避免创建后调用方改动同一缓冲区影响审批内容/摘要
562	    const data = Buffer.from((dataField as Uint8Array | undefined) ?? new Uint8Array());
563	
564	    const req: TransactionApprovalRequest = {
565	      walletId: this.id,
566	      version: this.version,
567	      nonce,
568	      deadline,
569	      to,
570	      value,
571	      data,
572	    };
573	    const digest = hashTransactionApproval(req);
574	    const id = createHash('sha256')
575	      .update(`approval:${this.approvalSeq}:${digest.toString('hex')}`)
576	      .digest('hex')
577	      .slice(0, 16);
578	    this.approvalSeq += 1;
579	
580	    const record: ApprovalRecord = {
581	      id,
582	      digest,
583	      version: this.version,
584	      confirmations: this.confirmations,
585	      nonce,
586	      deadline,
587	      to,
588	      value,
589	      data,
590	      signers: [],
591	      signatures: new Map(),
592	      submitted: false,
593	    };
594	    this.approvals.set(id, record);
595	    return this.approvalSnapshot(record);
596	  }
