598	  /**
599	   * 给审批追加一个 65 字节签名（每次一个）。
600	   *
601	   * 校验顺序：
602	   *   1) 审批不存在 → ApprovalNotFoundError
603	   *   2) 已提交 → ApprovalAlreadySubmittedError
604	   *   3) 已过期 → ApprovalExpiredError（过期优先于版本冲突）
605	   *   4) 策略版本漂移 → ApprovalPolicyConflictError
606	   *   5) 签名格式 / 与摘要不符 / 签名者非当前所有者 → InvalidApprovalSignatureError
607	   *   6) 同一所有者重复加签 → DuplicateApprovalSignatureError
608	   *
609	   * 达到创建时确认数后状态变为 ready；任一失败都不改变审批内容。
610	   */
611	  addApprovalSignature(approvalId: string, signature: Uint8Array): TransactionApproval {
612	    const record = this.getApprovalRecord(approvalId);
613	    this.assertApprovalActive(record);
614	
615	    if (!(signature instanceof Uint8Array) || signature.length !== 65) {
616	      throw new InvalidApprovalSignatureError('signature must be a 65-byte r||s||v blob');
617	    }
618	    const signer = recoverAddress(record.digest, Uint8Array.from(signature));
619	    if (signer === null) {
620	      throw new InvalidApprovalSignatureError('malformed or non-canonical signature');
621	    }
622	    if (!this.ownerSet.has(signer)) {
623	      throw new InvalidApprovalSignatureError('signature does not match approval or signer is not an owner');
624	    }
625	    if (record.signatures.has(signer)) {
626	      throw new DuplicateApprovalSignatureError(`owner already signed: ${signer}`);
627	    }
628	    record.signers.push(signer);
629	    record.signatures.set(signer, Buffer.from(signature));
630	    return this.approvalSnapshot(record);
631	  }
