633	  /** 查询审批快照（状态与按加签顺序的签名者）；未知 id 抛 ApprovalNotFoundError */
634	  getTransactionApproval(approvalId: string): TransactionApproval {
635	    return this.approvalSnapshot(this.getApprovalRecord(approvalId));
636	  }
