638	  /**
639	   * 阈值满足后提交审批：按既有 safe-wallet/tx/v1 摘要入队一个普通交易任务，
640	   * 只消费创建时绑定的 nonce 并推进 expectedNonce；队列与既有终态行为不变。
641	   *
642	   * 校验顺序（任一失败都不消费 nonce、不建任务、不改策略）：
643	   *   1) 审批不存在 → ApprovalNotFoundError；已提交 → ApprovalAlreadySubmittedError
644	   *   2) 已过期 → ApprovalExpiredError；版本漂移 → ApprovalPolicyConflictError（过期优先）
645	   *   3) 签名不足创建时确认数 → ApprovalThresholdNotMetError
646	   *   4) nonce 已消费 → NonceAlreadyUsedError；nonce ≠ expectedNonce → ApprovalNonceConflictError
647	   */
648	  submitApprovedTransaction(approvalId: string): WalletTask {
649	    const record = this.getApprovalRecord(approvalId);
650	    this.assertApprovalActive(record);
651	
652	    if (BigInt(record.signers.length) < record.confirmations) {
653	      throw new ApprovalThresholdNotMetError(
654	        `threshold not met: need ${record.confirmations} distinct owners, got ${record.signers.length}`,
655	      );
656	    }
657	    if (this.usedNonces.has(record.nonce)) throw new NonceAlreadyUsedError(record.nonce);
658	    if (record.nonce !== this.nextNonce) {
659	      throw new ApprovalNonceConflictError(`expected nonce ${this.nextNonce}, got ${record.nonce}`);
660	    }
661	
662	    // 按既有普通交易摘要入队（与 submitTransaction 同一域、同一载荷形状）
663	    const req: TransactionRequest = {
664	      walletId: this.id,
665	      nonce: record.nonce,
666	      deadline: record.deadline,
667	      to: record.to,
668	      value: record.value,
669	      data: record.data,
670	    };
671	    const digest = hashTransaction(req);
672	    const payload: WalletTaskPayload = {
673	      kind: 'transaction',
674	      deadline: record.deadline,
675	      to: record.to,
676	      value: record.value,
677	      data: Buffer.from(record.data),
678	    };
679	    let task: WalletTask;
680	    try {
681	      task = this.queue.enqueue({
682	        nonce: record.nonce,
683	        digest: digest.toString('hex'),
684	        payload,
685	        submittedAt: this.now(),
686	      });
687	    } catch (err) {
688	      if (err instanceof InvalidQueueStateError) throw new InvalidTransaction(err.message);
689	      throw err;
690	    }
691	    // 原子生效：入队 + 消费 nonce + 审批进入 submitted 终态
692	    this.usedNonces.add(record.nonce);
693	    this.nextNonce = record.nonce + 1n;
694	    record.submitted = true;
695	    return task;
696	  }
