698	  // ---------- 策略变更分阶段审批（签名收集与提交分离；直接 proposePolicyChange 不变） ----------
699	
700	  /**
701	   * 创建一次策略变更的分阶段审批：只校验并登记，不消费 nonce、不建任务、不改策略。
702	   *
703	   * 审批摘要用 safe-wallet/policy-change-approval/v1 域，绑定钱包标识、创建时策略版本、nonce、
704	   * 截止时间与目标新策略（新确认数、按顺序编码的新所有者列表），与直接提交的
705	   * safe-wallet/policy-change/v1 摘要互不通用。
706	   *
707	   * 校验顺序与 proposePolicyChange 一致（失败不产生任何状态变化）：
708	   *   1) nonce 复用 → NonceAlreadyUsedError
709	   *   2) deadline 早于当前时间 → RequestExpired
710	   *   3) 字段 / 版本（须等于当前版本）/ nonce 顺序（须等于 expectedNonce）→ InvalidPolicyChange
711	   *
712	   * 同一 nonce 可登记多个候选审批（创建不消费 nonce）；成功返回审批快照（空签名者、
713	   * collecting 状态）。
714	   */
715	  createPolicyApproval(sub: PolicyChangeSubmission): PolicyApproval {
716	    // (1) nonce 安全转换与复用判定（复用优先于过期，与既有提交一致）
717	    const nonce = toBigInt(sub.nonce, InvalidPolicyChange, 'nonce');
718	    if (!isNonNegativeInteger(nonce)) throw new InvalidPolicyChange('nonce must be a non-negative integer');
719	    if (this.usedNonces.has(nonce)) throw new NonceAlreadyUsedError(nonce);
720	
721	    // (2) 截止时间
722	    const deadline = toBigInt(sub.deadline, InvalidPolicyChange, 'deadline');
723	    if (!isNonNegativeInteger(deadline)) throw new InvalidPolicyChange('deadline out of range');
724	    if (deadline < this.now()) {
725	      throw new RequestExpired(`request deadline ${deadline} already passed`);
726	    }
727	    // (3) nonce 顺序：创建只登记不消费，但仍须绑定当前期望 nonce（跳号即非法）
728	    if (nonce !== this.nextNonce) {
729	      throw new InvalidPolicyChange(`expected nonce ${this.nextNonce}, got ${nonce}`);
730	    }
731	
732	    // (4) 版本与目标策略字段校验（与直接提交同一套规则；版本须等于当前版本）
733	    const { version, newOwners, newConfirmations } = this.normalizePolicyChangeFields({
734	      version: sub.version,
735	      newOwners: sub.newOwners,
736	      newConfirmations: sub.newConfirmations,
737	    });
738	
739	    const req: PolicyApprovalRequest = {
740	      walletId: this.id,
741	      version,
742	      nonce,
743	      deadline,
744	      newOwners,
745	      newConfirmations,
746	    };
747	    const digest = hashPolicyApproval(req);
748	    const id = createHash('sha256')
749	      .update(`policy-approval:${this.policyApprovalSeq}:${digest.toString('hex')}`)
750	      .digest('hex')
751	      .slice(0, 16);
752	    this.policyApprovalSeq += 1;
753	
754	    const record: PolicyApprovalRecord = {
755	      id,
756	      digest,
757	      version,
758	      confirmations: this.confirmations,
759	      nonce,
760	      deadline,
761	      newOwners,
762	      newConfirmations,
763	      signers: [],
764	      signatures: new Map(),
765	      submitted: false,
766	    };
767	    this.policyApprovals.set(id, record);
768	    return this.policyApprovalSnapshot(record);
769	  }
