785	    const record = this.getPolicyApprovalRecord(approvalId);
786	    this.assertPolicyApprovalActive(record);
787	
788	    if (!(signature instanceof Uint8Array) || signature.length !== 65) {
789	      throw new InvalidApprovalSignatureError('signature must be a 65-byte r||s||v blob');
790	    }
791	    const signer = recoverAddress(record.digest, Uint8Array.from(signature));
792	    if (signer === null) {
793	      throw new InvalidApprovalSignatureError('malformed or non-canonical signature');
794	    }
795	    if (!this.ownerSet.has(signer)) {
796	      throw new InvalidApprovalSignatureError('signature does not match approval or signer is not an owner');
797	    }
798	    if (record.signatures.has(signer)) {
799	      throw new DuplicateApprovalSignatureError(`owner already signed: ${signer}`);
800	    }
801	    record.signers.push(signer);
802	    record.signatures.set(signer, Buffer.from(signature));
