816	  /**
817	   * 阈值满足后提交策略变更审批：按既有 safe-wallet/policy-change/v1 摘要入队一个
818	   * policy-change 任务，只消费创建时绑定的 nonce 并推进 expectedNonce；策略本身不在提交时
819	   * 改变，要到任务执行成功才替换所有者/确认数并递增版本。队列与既有终态行为不变：执行时若
820	   * 版本已漂移，任务按既有 PolicyConflict 进入 failed 终态，不改策略。
821	   *
822	   * 校验顺序（任一失败都不消费 nonce、不建任务、不改策略）：
823	   *   1) 审批不存在 → ApprovalNotFoundError；已提交 → ApprovalAlreadySubmittedError
824	   *   2) 已过期 → ApprovalExpiredError；版本漂移 → ApprovalPolicyConflictError（过期优先）
825	   *   3) 签名不足创建时确认数 → ApprovalThresholdNotMetError
826	   *   4) nonce 已消费 → NonceAlreadyUsedError；nonce ≠ expectedNonce（未消费但顺序错）
827	   *      → ApprovalNonceConflictError
828	   */
829	  submitApprovedPolicyChange(approvalId: string): WalletTask {
830	    const record = this.getPolicyApprovalRecord(approvalId);
831	    this.assertPolicyApprovalActive(record);
832	
833	    if (BigInt(record.signers.length) < record.confirmations) {
834	      throw new ApprovalThresholdNotMetError(
835	        `threshold not met: need ${record.confirmations} distinct owners, got ${record.signers.length}`,
836	      );
837	    }
838	    if (this.usedNonces.has(record.nonce)) throw new NonceAlreadyUsedError(record.nonce);
839	    if (record.nonce !== this.nextNonce) {
840	      throw new ApprovalNonceConflictError(`expected nonce ${this.nextNonce}, got ${record.nonce}`);
841	    }
842	
843	    // 按既有策略变更摘要入队（与 proposePolicyChange 同一域、同一载荷形状）
844	    const req: PolicyChangeRequest = {
845	      walletId: this.id,
846	      version: record.version,
847	      nonce: record.nonce,
848	      deadline: record.deadline,
849	      newOwners: record.newOwners,
850	      newConfirmations: record.newConfirmations,
851	    };
852	    const digest = hashPolicyChange(req);
853	    const payload: WalletTaskPayload = {
854	      kind: 'policy-change',
855	      deadline: record.deadline,
856	      version: record.version,
857	      newOwners: [...record.newOwners],
858	      newConfirmations: record.newConfirmations,
859	    };
860	    let task: WalletTask;
861	    try {
862	      task = this.queue.enqueue({
863	        nonce: record.nonce,
864	        digest: digest.toString('hex'),
865	        payload,
866	        submittedAt: this.now(),
867	      });
868	    } catch (err) {
869	      if (err instanceof InvalidQueueStateError) throw new InvalidPolicyChange(err.message);
870	      throw err;
871	    }
872	    // 原子生效：入队 + 消费 nonce + 审批进入 submitted 终态（策略在执行成功时才改变）
873	    this.usedNonces.add(record.nonce);
874	    this.nextNonce = record.nonce + 1n;
875	    record.submitted = true;
876	    return task;
877	  }
