881	  /**
882	   * 创建一个批量交易的分阶段审批：只校验并登记，不消费 nonce、不建任务、不改策略。
883	   *
884	   * 审批摘要用 safe-wallet/tx-batch-approval/v1 域，绑定钱包标识、创建时策略版本、nonce、
885	   * 截止时间与按顺序编码的全部调用（每调用固定按“收款地址 || 金额 || data”编码，再以
886	   * encList 绑定项数与顺序），与直接提交的 safe-wallet/tx-batch/v1 摘要互不通用。
887	   *
888	   * 校验顺序与 submitBatchTransaction 一致（失败不产生任何状态变化）：
889	   *   1) nonce 复用 → NonceAlreadyUsedError
890	   *   2) deadline 早于当前时间 → RequestExpired
891	   *   3) nonce 跳号（须等于 expectedNonce）、列表（1..64 项）、收款地址、金额、data
892	   *      → InvalidTransactionBatch
893	   *
894	   * 同一 nonce 可登记多个候选审批（创建不消费 nonce）；成功返回审批快照（空签名者、
895	   * collecting 状态）。
896	   */
897	  createBatchApproval(sub: BatchTransactionSubmission): BatchApproval {
898	    // (1) nonce 安全转换与复用判定（复用优先于过期，与既有提交一致）
899	    const nonce = toBigInt(sub.nonce, InvalidTransactionBatch, 'nonce');
900	    if (!isNonNegativeInteger(nonce)) {
901	      throw new InvalidTransactionBatch('nonce must be a non-negative integer');
902	    }
903	    if (this.usedNonces.has(nonce)) throw new NonceAlreadyUsedError(nonce);
904	
905	    // (2) 截止时间
906	    const deadline = toBigInt(sub.deadline, InvalidTransactionBatch, 'deadline');
907	    if (!isNonNegativeInteger(deadline)) throw new InvalidTransactionBatch('deadline out of range');
908	    if (deadline < this.now()) {
909	      throw new RequestExpired(`request deadline ${deadline} already passed`);
910	    }
911	    // (3) nonce 顺序：创建只登记不消费，但仍须绑定当前期望 nonce（跳号即非法）
912	    if (nonce !== this.nextNonce) {
913	      throw new InvalidTransactionBatch(`expected nonce ${this.nextNonce}, got ${nonce}`);
914	    }
915	
916	    // (4) 有序调用列表校验与规范化（与直接提交同一套规则；data 复制保存）
917	    const calls = this.normalizeBatchCalls(sub.calls);
918	
919	    const req: TransactionBatchApprovalRequest = {
920	      walletId: this.id,
921	      version: this.version,
922	      nonce,
923	      deadline,
924	      calls,
925	    };
926	    const digest = hashBatchApproval(req);
927	    const id = createHash('sha256')
928	      .update(`batch-approval:${this.batchApprovalSeq}:${digest.toString('hex')}`)
929	      .digest('hex')
930	      .slice(0, 16);
931	    this.batchApprovalSeq += 1;
932	
933	    const record: BatchApprovalRecord = {
934	      id,
935	      digest,
936	      version: this.version,
937	      confirmations: this.confirmations,
938	      nonce,
939	      deadline,
940	      calls,
941	      signers: [],
942	      signatures: new Map(),
943	      submitted: false,
944	    };
945	    this.batchApprovals.set(id, record);
946	    return this.batchApprovalSnapshot(record);
947	  }
