1070	  /**
1071	   * 统一提交入口。raw 接收未经转换的原始标量（bigint/number/string），
1072	   * 所有转换与字段合法性判定都在这里完成，保证只能抛出约定错误类型。
1073	   */
1074	  private submit(
1075	    kind: WalletTaskPayload['kind'],
1076	    raw: Record<string, unknown>,
1077	    signatures: readonly Uint8Array[],
1078	  ): WalletTask {
1079	    const Invalid =
1080	      kind === 'policy-change'
1081	        ? InvalidPolicyChange
1082	        : kind === 'transaction-batch'
1083	          ? InvalidTransactionBatch
1084	          : InvalidTransaction;
1085	
1086	    // 校验优先级（任一失败都不建任务、不消费 nonce、不改策略）：
1087	    //   1) nonce 复用 → 既有重放防护的公开异常（旧请求重放即使已过期也仍报复用）
1088	    //   2) 截止时间早于当前时间 → RequestExpired
1089	    //   3) 字段 / 版本 / nonce 顺序 / 签名 → 对应 Invalid*
1090	    const nonce = toBigInt(raw.nonce, Invalid, 'nonce');
1091	    if (!isNonNegativeInteger(nonce)) throw new Invalid('nonce must be a non-negative integer');
1092	    if (this.usedNonces.has(nonce)) throw new NonceAlreadyUsedError(nonce);
1093	
1094	    const deadline = toBigInt(raw.deadline, Invalid, 'deadline');
1095	    if (!isNonNegativeInteger(deadline)) throw new Invalid('deadline out of range');
1096	    if (deadline < this.now()) {
1097	      throw new RequestExpired(`request deadline ${deadline} already passed`);
1098	    }
1099	    if (nonce !== this.nextNonce) throw new Invalid(`expected nonce ${this.nextNonce}, got ${nonce}`);
1100	
1101	    // (3) 字段校验 + 规范化
1102	    let payload: WalletTaskPayload;
1103	    let digest: Buffer;
1104	    if (kind === 'transaction') {
1105	      const to = normalizeAddress(raw.to as string);
1106	      if (to === null || isZeroAddress(to)) throw new Invalid('invalid or zero recipient address');
1107	      const value = toBigInt(raw.value, Invalid, 'value');
1108	      if (!isNonNegativeInteger(value)) throw new Invalid('value out of range');
1109	      const dataField = raw.data;
1110	      if (
1111	        dataField !== undefined &&
1112	        !(dataField instanceof Uint8Array) &&
1113	        !ArrayBuffer.isView(dataField)
1114	      ) {
1115	        throw new Invalid('data must be a byte array');
1116	      }
1117	      const data = Buffer.from((dataField as Uint8Array | undefined) ?? new Uint8Array());
1118	      const req: TransactionRequest = {
1119	        walletId: this.id,
1120	        nonce,
1121	        deadline,
1122	        to,
1123	        value,
1124	        data,
1125	      };
1126	      digest = hashTransaction(req);
1127	      payload = { kind: 'transaction', deadline, to, value, data };
1128	    } else if (kind === 'transaction-batch') {
1129	      // 有序调用列表：1..64 项；逐项规范化收款地址、金额与 data（顺序保持不变）
1130	      const calls = this.normalizeBatchCalls(raw.calls);
1131	      const req: TransactionBatchRequest = {
1132	        walletId: this.id,
1133	        nonce,
1134	        deadline,
1135	        calls,
1136	      };
1137	      digest = hashTransactionBatch(req);
1138	      payload = { kind: 'transaction-batch', deadline, calls };
1139	    } else {
1140	      // (3) 版本与目标策略字段（直接提交与分阶段审批共用同一套规则）
1141	      const { version, newOwners, newConfirmations } = this.normalizePolicyChangeFields(raw);
1142	      const req: PolicyChangeRequest = {
1143	        walletId: this.id,
1144	        version,
1145	        nonce,
1146	        deadline,
1147	        newOwners,
1148	        newConfirmations,
1149	      };
1150	      digest = hashPolicyChange(req);
1151	      payload = { kind: 'policy-change', deadline, version, newOwners, newConfirmations };
1152	    }
1153	
1154	    // (4) 阈值签名：恢复 → 去重 → 必须为当前所有者 → 数量达到当前确认数
1155	    this.verifyThresholdSignatures(digest, signatures, Invalid);
1156	
1157	    // (5) 原子生效（到队列为止）：入队 + 消费 nonce。
1158	    //     入队失败（同一摘要重复等）时不消费 nonce。
1159	    let task: WalletTask;
1160	    try {
1161	      task = this.queue.enqueue({
1162	        nonce,
1163	        digest: digest.toString('hex'),
1164	        payload,
1165	        submittedAt: this.now(),
1166	      });
1167	    } catch (err) {
1168	      if (err instanceof InvalidQueueStateError) throw new Invalid(err.message);
1169	      throw err;
1170	    }
1171	    this.usedNonces.add(nonce);
1172	    this.nextNonce = nonce + 1n;
1173	    return task;
1174	  }
