1211	  /**
1212	   * 规范化策略变更字段（直接提交 proposePolicyChange 与分阶段审批 createPolicyApproval 共用）：
1213	   *   - 版本必须绑定当前版本（提交/创建时不匹配 → InvalidPolicyChange；执行时漂移 → PolicyConflict）
1214	   *   - 新所有者列表非空、无重复、无零地址、全部合法（保持输入顺序）
1215	   *   - 新确认数大于 0 且不超过新所有者数量
1216	   * 任一不合法都抛 InvalidPolicyChange；成功返回规范化后的值。
1217	   */
1218	  private normalizePolicyChangeFields(raw: Record<string, unknown>): {
1219	    version: bigint;
1220	    newOwners: Address[];
1221	    newConfirmations: bigint;
1222	  } {
1223	    const version = toBigInt(raw.version, InvalidPolicyChange, 'version');
1224	    if (version !== this.version) {
1225	      throw new InvalidPolicyChange(
1226	        `policy version mismatch: bound ${version}, current ${this.version}`,
1227	      );
1228	    }
1229	    const newOwners = normalizeOwnerList(raw.newOwners as string[], InvalidPolicyChange);
1230	    const newConfirmations = toBigInt(raw.newConfirmations, InvalidPolicyChange, 'newConfirmations');
1231	    if (newConfirmations <= 0n || newConfirmations > BigInt(newOwners.length)) {
1232	      throw new InvalidPolicyChange(
1233	        `new confirmations must be within 1..new owners (${newOwners.length}), got ${newConfirmations}`,
1234	      );
1235	    }
1236	    return { version, newOwners, newConfirmations };
1237	  }
1238	
1239	  // ---------- 分阶段审批内部辅助 ----------
1240	
1241	  private getApprovalRecord(approvalId: string): ApprovalRecord {
1242	    const record = typeof approvalId === 'string' ? this.approvals.get(approvalId) : undefined;
1243	    if (record === undefined) throw new ApprovalNotFoundError(`approval not found: ${String(approvalId)}`);
1244	    return record;
1245	  }
1246	
1247	  /** 已提交 / 已过期 / 版本漂移的审批不可再加签或提交（过期优先于版本冲突） */
1248	  private assertApprovalActive(record: ApprovalRecord): void {
1249	    if (record.submitted) throw new ApprovalAlreadySubmittedError(`approval ${record.id} already submitted`);
1250	    if (record.deadline < this.now()) {
1251	      throw new ApprovalExpiredError(`approval deadline ${record.deadline} already passed`);
1252	    }
1253	    if (record.version !== this.version) {
1254	      throw new ApprovalPolicyConflictError(
1255	        `policy version drifted: approval bound ${record.version}, current ${this.version}`,
1256	      );
1257	    }
1258	  }
1259	
1260	  /** 派生状态：submitted > expired > conflicted > ready > collecting */
1261	  private approvalStatus(record: ApprovalRecord): ApprovalStatus {
1262	    if (record.submitted) return 'submitted';
1263	    if (record.deadline < this.now()) return 'expired';
1264	    if (record.version !== this.version) return 'conflicted';
1265	    return BigInt(record.signers.length) >= record.confirmations ? 'ready' : 'collecting';
1266	  }
1267	
1268	  private approvalSnapshot(record: ApprovalRecord): TransactionApproval {
1269	    return {
1270	      id: record.id,
1271	      digest: record.digest.toString('hex'),
1272	      version: record.version,
1273	      confirmations: record.confirmations,
1274	      signers: [...record.signers],
1275	      status: this.approvalStatus(record),
1276	    };
1277	  }
1278	
1279	  // ---------- 策略变更分阶段审批内部辅助 ----------
1280	
1281	  private getPolicyApprovalRecord(approvalId: string): PolicyApprovalRecord {
1282	    const record =
1283	      typeof approvalId === 'string' ? this.policyApprovals.get(approvalId) : undefined;
1284	    if (record === undefined) {
1285	      throw new ApprovalNotFoundError(`policy approval not found: ${String(approvalId)}`);
1286	    }
1287	    return record;
1288	  }
1289	
1290	  /** 已提交 / 已过期 / 版本漂移的策略审批不可再加签或提交（过期优先于版本冲突） */
1291	  private assertPolicyApprovalActive(record: PolicyApprovalRecord): void {
1292	    if (record.submitted) {
1293	      throw new ApprovalAlreadySubmittedError(`policy approval ${record.id} already submitted`);
1294	    }
1295	    if (record.deadline < this.now()) {
1296	      throw new ApprovalExpiredError(`policy approval deadline ${record.deadline} already passed`);
1297	    }
1298	    if (record.version !== this.version) {
1299	      throw new ApprovalPolicyConflictError(
1300	        `policy version drifted: approval bound ${record.version}, current ${this.version}`,
1301	      );
1302	    }
1303	  }
1304	
1305	  /** 派生状态：submitted > expired > conflicted > ready > collecting（与普通交易审批同一序） */
1306	  private policyApprovalStatus(record: PolicyApprovalRecord): ApprovalStatus {
1307	    if (record.submitted) return 'submitted';
1308	    if (record.deadline < this.now()) return 'expired';
1309	    if (record.version !== this.version) return 'conflicted';
1310	    return BigInt(record.signers.length) >= record.confirmations ? 'ready' : 'collecting';
1311	  }
1312	
1313	  private policyApprovalSnapshot(record: PolicyApprovalRecord): PolicyApproval {
1314	    return {
1315	      id: record.id,
1316	      digest: record.digest.toString('hex'),
1317	      version: record.version,
1318	      confirmations: record.confirmations,
1319	      nonce: record.nonce,
1320	      deadline: record.deadline,
1321	      newOwners: [...record.newOwners],
1322	      newConfirmations: record.newConfirmations,
1323	      signers: [...record.signers],
1324	      status: this.policyApprovalStatus(record),
1325	    };
1326	  }
1327	
1328	  // ---------- 批量交易分阶段审批内部辅助 ----------
1329	
1330	  private getBatchApprovalRecord(approvalId: string): BatchApprovalRecord {
1331	    const record =
1332	      typeof approvalId === 'string' ? this.batchApprovals.get(approvalId) : undefined;
1333	    if (record === undefined) {
1334	      throw new ApprovalNotFoundError(`batch approval not found: ${String(approvalId)}`);
1335	    }
1336	    return record;
1337	  }
1338	
1339	  /** 已提交 / 已过期 / 版本漂移的批量审批不可再加签或提交（过期优先于版本冲突） */
1340	  private assertBatchApprovalActive(record: BatchApprovalRecord): void {
1341	    if (record.submitted) {
1342	      throw new ApprovalAlreadySubmittedError(`batch approval ${record.id} already submitted`);
1343	    }
1344	    if (record.deadline < this.now()) {
1345	      throw new ApprovalExpiredError(`batch approval deadline ${record.deadline} already passed`);
1346	    }
1347	    if (record.version !== this.version) {
1348	      throw new ApprovalPolicyConflictError(
1349	        `policy version drifted: approval bound ${record.version}, current ${this.version}`,
1350	      );
1351	    }
1352	  }
1353	
1354	  /** 派生状态：submitted > expired > conflicted > ready > collecting（与其他审批同一序） */
1355	  private batchApprovalStatus(record: BatchApprovalRecord): ApprovalStatus {
1356	    if (record.submitted) return 'submitted';
1357	    if (record.deadline < this.now()) return 'expired';
1358	    if (record.version !== this.version) return 'conflicted';
1359	    return BigInt(record.signers.length) >= record.confirmations ? 'ready' : 'collecting';
1360	  }
1361	
1362	  private batchApprovalSnapshot(record: BatchApprovalRecord): BatchApproval {
1363	    return {
1364	      id: record.id,
1365	      digest: record.digest.toString('hex'),
1366	      version: record.version,
1367	      confirmations: record.confirmations,
1368	      nonce: record.nonce,
1369	      deadline: record.deadline,
1370	      calls: record.calls.map((call) => ({ to: call.to, value: call.value, data: Buffer.from(call.data) })),
1371	      signers: [...record.signers],
1372	      status: this.batchApprovalStatus(record),
1373	    };
1374	  }
1375	
1376	  /** 按“当前策略”的所有者集合与确认数校验签名收集 */
1377	  private verifyThresholdSignatures(
1378	    digest: Uint8Array,
1379	    signatures: readonly Uint8Array[],
1380	    Invalid: new (msg: string) => Error,
1381	  ): void {
1382	    if (!Array.isArray(signatures)) {
1383	      throw new Invalid('signatures must be an array');
1384	    }
1385	    if (signatures.length === 0) throw new Invalid('missing signatures');
1386	
1387	    const signedBy = new Set<Address>();
1388	    for (const sig of signatures) {
1389	      if (!(sig instanceof Uint8Array) || sig.length !== 65) {
1390	        throw new Invalid('each signature must be a 65-byte r||s||v blob');
1391	      }
1392	      const signer = recoverAddress(digest, Uint8Array.from(sig));
1393	      if (signer === null) throw new Invalid('malformed or non-canonical signature');
1394	      if (!this.ownerSet.has(signer)) {
1395	        // 非所有者签名：既可能是伪造，也可能是签名载荷与提交内容不匹配
1396	        throw new Invalid('signature does not match payload or signer is not an owner');
1397	      }
1398	      signedBy.add(signer); // 地址去重：同一所有者多签只计一次
1399	    }
1400	    if (BigInt(signedBy.size) < this.confirmations) {
1401	      throw new Invalid(
1402	        `threshold not met: need ${this.confirmations} distinct owners, got ${signedBy.size}`,
1403	      );
1404	    }
1405	  }
1406	
1407	  /** 队列执行器回调：定义各类任务的生效语义 */
1408	  private applyTask(task: WalletTask): unknown {
1409	    const p = task.payload;
1410	    if (p.kind === 'transaction') {
1411	      // 普通交易既有执行结果：一个可观察的执行产物；不触碰策略状态。
1412	      // 截止时间只在提交阶段核对（RequestExpired），不作为执行闸门，以保持既有执行结果不变。
1413	      return {
1414	        kind: 'transfer',
1415	        to: p.to,
1416	        value: p.value,
1417	        data: Buffer.from(p.data).toString('hex'),
1418	      };
1419	    }
1420	
1421	    if (p.kind === 'transaction-batch') {
1422	      // 原子批量：执行器一次性产出整批回执。调用方（队列）在本回调正常返回后才写入
1423	      // executed 终态；本回调抛出则整批进入 failed，不产生部分执行回执。
1424	      // 截止时间同样不是执行闸门，与单笔普通交易保持一致。
1425	      return {
1426	        kind: 'transfer-batch',
1427	        calls: p.calls.map((call) => ({
1428	          to: call.to,
1429	          value: call.value,
1430	          data: Buffer.from(call.data).toString('hex'),
1431	        })),
1432	      };
1433	    }
1434	
1435	    // 策略变更：仅当绑定版本仍等于当前版本时生效
1436	    if (p.version !== this.version) {
1437	      throw new PolicyConflict(
1438	        `policy version drifted: task bound ${p.version}, current ${this.version}`,
1439	      );
1440	    }
1441	    // 所有者集合与确认数同时替换；版本恰好递增一次
1442	    this.owners = [...p.newOwners];
1443	    this.ownerSet.clear();
1444	    for (const o of this.owners) this.ownerSet.add(o);
1445	    this.confirmations = p.newConfirmations;
1446	    this.version += 1n;
1447	    return {
1448	      kind: 'policy-applied',
1449	      version: this.version,
1450	      owners: [...this.owners],
1451	      confirmations: this.confirmations,
1452	    };
1453	  }
1454	}
1455	
1456	// ---------- 所有者列表规范化（空/重复/零地址校验） ----------
1457	
1458	function normalizeOwnerList(
1459	  input: readonly string[],
1460	  ErrorCtor: typeof InvalidPolicyChange | typeof InvalidTransaction = InvalidPolicyChange,
1461	): Address[] {
1462	  if (!Array.isArray(input) || input.length === 0) {
1463	    throw new ErrorCtor('owners list must be a non-empty array');
1464	  }
1465	  const out: Address[] = [];
1466	  const seen = new Set<Address>();
1467	  for (const raw of input) {
1468	    const addr = normalizeAddress(raw);
1469	    if (addr === null) throw new ErrorCtor(`invalid owner address: ${String(raw)}`);
1470	    if (addr === ZERO_ADDRESS || isZeroAddress(addr)) {
1471	      throw new ErrorCtor('zero address is not allowed as owner');
1472	    }
1473	    if (seen.has(addr)) throw new ErrorCtor(`duplicate owner: ${addr}`);
1474	    seen.add(addr);
1475	    out.push(addr);
1476	  }
1477	  return out;
1478	}
