1	/**
2	 * 规范化编码与签名摘要。
3	 *
4	 * 各类操作使用不同的域分隔标签，签名互不兼容（任一类型的签名都不能用于其他类型）：
5	 *   - 普通交易：         "safe-wallet/tx/v1"
6	 *   - 原子批量交易：     "safe-wallet/tx-batch/v1"
7	 *   - 策略变更：         "safe-wallet/policy-change/v1"
8	 *   - 任务取消：         "safe-wallet/cancel/v1"
9	 *   - 普通交易分阶段审批："safe-wallet/tx-approval/v1"
10	 *   - 策略变更分阶段审批："safe-wallet/policy-change-approval/v1"
11	 *   - 批量交易分阶段审批："safe-wallet/tx-batch-approval/v1"
12	 *
13	 * 编码规则（全部大端）：
14	 *   encBytes(b)  = uint32(len) || b
15	 *   encStr(s)    = uint32(len) || utf8(s)
16	 *   encUint(n)   = n 的定长 32 字节大端表示
17	 *   encList(xs)  = uint32(count) || concat(encBytes(x))
18	 *
19	 * 普通交易载荷不包含策略版本字段（保持既有交易格式不变）；
20	 * 批量交易载荷绑定钱包标识、nonce、截止时间，以及按顺序编码的全部调用
21	 * （每调用固定按“收款地址 || 金额 || data”编码，再以 encList 绑定项数与顺序）；
22	 * 策略变更载荷显式绑定钱包标识、操作标签、当前版本、新所有者、新确认数、nonce、截止时间。
23	 */
24	
25	import { sha256, hexToBytes, type Address } from './crypto.ts';
26	
27	const TAG_TX = 'safe-wallet/tx/v1';
28	const TAG_TX_BATCH = 'safe-wallet/tx-batch/v1';
29	const TAG_POLICY_CHANGE = 'safe-wallet/policy-change/v1';
30	const TAG_CANCEL = 'safe-wallet/cancel/v1';
31	const TAG_TX_APPROVAL = 'safe-wallet/tx-approval/v1';
32	const TAG_POLICY_APPROVAL = 'safe-wallet/policy-change-approval/v1';
33	const TAG_BATCH_APPROVAL = 'safe-wallet/tx-batch-approval/v1';
34	
35	// ---------- 编码原语 ----------
36	
37	export function encBytes(data: Uint8Array): Buffer {
38	  const b = Buffer.from(data);
39	  const out = Buffer.alloc(4 + b.length);
40	  out.writeUInt32BE(b.length, 0);
41	  b.copy(out, 4);
42	  return out;
43	}
44	
45	export function encStr(s: string): Buffer {
46	  return encBytes(Buffer.from(s, 'utf8'));
47	}
48	
49	export function encUint(n: bigint | number): Buffer {
50	  const v = BigInt(n);
51	  if (v < 0n) throw new Error('cannot encode negative integer');
52	  if (v >> 256n !== 0n) throw new Error('integer exceeds 32 bytes');
53	  const out = Buffer.alloc(32);
54	  let x = v;
55	  for (let i = 31; i >= 0; i--) {
56	    out[i] = Number(x & 0xffn);
57	    x >>= 8n;
58	  }
59	  return out;
60	}
61	
62	export function encList(items: Uint8Array[]): Buffer {
63	  const head = Buffer.alloc(4);
64	  head.writeUInt32BE(items.length, 0);
65	  return Buffer.concat([head, ...items.map(encBytes)]);
66	}
67	
68	function digest(tag: string, parts: Buffer[]): Buffer {
69	  return sha256(Buffer.concat([encStr(tag), ...parts]));
70	}
71	
72	// ---------- 请求类型 ----------
73	
74	export interface TransactionRequest {
75	  /** 钱包标识（部署时确定；参与签名绑定，防止跨钱包重放） */
76	  walletId: string;
77	  nonce: bigint;
78	  /** Unix 秒级截止时间（也接受毫秒级大数；语义由调用方约定，引擎按数值比较） */
79	  deadline: bigint;
80	  to: Address;
81	  value: bigint;
82	  data: Uint8Array;
83	}
84	
85	export interface PolicyChangeRequest {
86	  walletId: string;
87	  /** 提交时绑定的当前策略版本 */
88	  version: bigint;
89	  nonce: bigint;
90	  deadline: bigint;
91	  newOwners: Address[];
92	  newConfirmations: bigint;
93	}
94	
95	/** 批量交易中的单次调用：收款地址、金额、附带数据 */
96	export interface BatchTransactionCall {
97	  to: Address;
98	  value: bigint;
99	  data: Uint8Array;
100	}
101	
102	export interface TransactionBatchRequest {
103	  /** 钱包标识（部署时确定；参与签名绑定，防止跨钱包重放） */
104	  walletId: string;
105	  nonce: bigint;
106	  deadline: bigint;
107	  /** 有序调用列表（1..64 项）；顺序参与签名，不得改变 */
108	  calls: BatchTransactionCall[];
109	}
110	
111	export interface CancellationRequest {
112	  walletId: string;
113	  /** 目标任务的签名摘要（hex）：把取消请求绑定到唯一任务，防止改绑其他任务 */
114	  taskDigest: string;
115	  nonce: bigint;
116	  deadline: bigint;
117	}
118	
119	export interface TransactionApprovalRequest {
120	  walletId: string;
121	  /** 创建审批时绑定的当前策略版本 */
122	  version: bigint;
123	  nonce: bigint;
124	  deadline: bigint;
125	  to: Address;
126	  value: bigint;
127	  data: Uint8Array;
128	}
129	
130	export interface PolicyApprovalRequest {
131	  walletId: string;
132	  /** 创建审批时绑定的当前策略版本 */
133	  version: bigint;
134	  nonce: bigint;
135	  deadline: bigint;
136	  /** 新所有者顺序（有序列表，顺序参与签名绑定） */
137	  newOwners: Address[];
138	  newConfirmations: bigint;
139	}
140	
141	export interface TransactionBatchApprovalRequest {
142	  walletId: string;
143	  /** 创建审批时绑定的当前策略版本 */
144	  version: bigint;
145	  nonce: bigint;
146	  deadline: bigint;
147	  /** 有序调用列表（1..64 项）；顺序参与签名，不得改变 */
148	  calls: BatchTransactionCall[];
149	}
150	
151	function walletIdBytes(walletId: string): Buffer {
152	  // 钱包标识统一按 UTF-8 参与签名绑定（任意字符串均可）
153	  return Buffer.from(walletId, 'utf8');
154	}
155	
156	function deadlineToBigint(d: bigint | number): bigint {
157	  return BigInt(d);
158	}
159	
160	/** 普通交易的签名摘要（不含策略版本字段） */
161	export function hashTransaction(req: {
162	  walletId: string;
163	  nonce: bigint | number;
164	  deadline: bigint | number;
165	  to: Address;
166	  value: bigint | number;
167	  data: Uint8Array;
168	}): Buffer {
169	  return digest(TAG_TX, [
170	    encBytes(walletIdBytes(req.walletId)),
171	    encUint(req.nonce),
172	    encUint(deadlineToBigint(req.deadline)),
173	    encBytes(hexToBytes(req.to)),
174	    encUint(req.value),
175	    encBytes(req.data),
176	  ]);
177	}
178	
179	/**
180	 * 原子批量普通交易的签名摘要：绑定钱包标识、nonce、截止时间，以及按顺序编码的全部调用。
181	 * 每个调用固定按“收款地址 || 金额 || data”编码为一段，再以 encList 绑定项数与顺序：
182	 * 任一调用的收款方/金额/data 变化，或调用顺序/项数变化，都会改变摘要。
183	 */
184	export function hashTransactionBatch(req: {
185	  walletId: string;
186	  nonce: bigint | number;
187	  deadline: bigint | number;
188	  calls: readonly {
189	    to: Address;
190	    value: bigint | number;
191	    data: Uint8Array;
192	  }[];
193	}): Buffer {
194	  const encodedCalls = req.calls.map((call) =>
195	    Buffer.concat([
196	      encBytes(hexToBytes(call.to)),
197	      encUint(call.value),
198	      encBytes(call.data),
199	    ]),
200	  );
201	  return digest(TAG_TX_BATCH, [
202	    encBytes(walletIdBytes(req.walletId)),
203	    encUint(req.nonce),
204	    encUint(deadlineToBigint(req.deadline)),
205	    encList(encodedCalls),
206	  ]);
207	}
208	
209	/** 策略变更的签名摘要：显式绑定版本、新所有者与新确认数 */
210	export function hashPolicyChange(req: {
211	  walletId: string;
212	  version: bigint | number;
213	  nonce: bigint | number;
214	  deadline: bigint | number;
215	  newOwners: Address[];
216	  newConfirmations: bigint | number;
217	}): Buffer {
218	  return digest(TAG_POLICY_CHANGE, [
219	    encBytes(walletIdBytes(req.walletId)),
220	    encUint(req.version),
221	    encUint(req.nonce),
222	    encUint(deadlineToBigint(req.deadline)),
223	    encUint(req.newConfirmations),
224	    encList(req.newOwners.map((o) => hexToBytes(o))),
225	  ]);
226	}
227	
228	/** 任务取消的签名摘要：绑定钱包标识、目标任务摘要、nonce 与截止时间 */
229	export function hashCancellation(req: {
230	  walletId: string;
231	  taskDigest: string;
232	  nonce: bigint | number;
233	  deadline: bigint | number;
234	}): Buffer {
235	  return digest(TAG_CANCEL, [
236	    encBytes(walletIdBytes(req.walletId)),
237	    encBytes(hexToBytes(req.taskDigest)),
238	    encUint(req.nonce),
239	    encUint(deadlineToBigint(req.deadline)),
240	  ]);
241	}
242	
243	/**
244	 * 普通交易分阶段审批的签名摘要：绑定钱包标识、创建时的策略版本与完整交易字段
245	 * （nonce、截止时间、收款地址、金额、data 副本）。与 safe-wallet/tx/v1 域不同，
246	 * 审批签名与直接提交签名互不通用；版本漂移后旧审批签名自然失效（由引擎按版本拦截）。
247	 */
248	export function hashTransactionApproval(req: {
249	  walletId: string;
250	  version: bigint | number;
251	  nonce: bigint | number;
252	  deadline: bigint | number;
253	  to: Address;
254	  value: bigint | number;
255	  data: Uint8Array;
256	}): Buffer {
257	  return digest(TAG_TX_APPROVAL, [
258	    encBytes(walletIdBytes(req.walletId)),
259	    encUint(req.version),
260	    encUint(req.nonce),
261	    encUint(deadlineToBigint(req.deadline)),
262	    encBytes(hexToBytes(req.to)),
263	    encUint(req.value),
264	    encBytes(req.data),
265	  ]);
266	}
267	
268	/**
269	 * 策略变更分阶段审批的签名摘要：绑定钱包标识、创建时策略版本、nonce、截止时间与目标新策略
270	 * （新确认数、按顺序编码的新所有者列表）。使用独立的 safe-wallet/policy-change-approval/v1
271	 * 域：与既有 safe-wallet/policy-change/v1 直接提交签名互不通用；版本漂移后旧审批签名自然失效
272	 * （由引擎按版本拦截）。新所有者列表顺序参与签名，顺序变化即改变摘要。
273	 */
274	export function hashPolicyApproval(req: {
275	  walletId: string;
276	  version: bigint | number;
277	  nonce: bigint | number;
278	  deadline: bigint | number;
279	  newOwners: Address[];
280	  newConfirmations: bigint | number;
281	}): Buffer {
282	  return digest(TAG_POLICY_APPROVAL, [
283	    encBytes(walletIdBytes(req.walletId)),
284	    encUint(req.version),
285	    encUint(req.nonce),
286	    encUint(deadlineToBigint(req.deadline)),
287	    encUint(req.newConfirmations),
288	    encList(req.newOwners.map((o) => hexToBytes(o))),
289	  ]);
290	}
291	
292	/**
293	 * 批量交易分阶段审批的签名摘要：绑定钱包标识、创建时策略版本、nonce、截止时间与按顺序编码的
294	 * 全部调用（每调用固定按“收款地址 || 金额 || data”编码，再以 encList 绑定项数与顺序）。
295	 * 使用独立的 safe-wallet/tx-batch-approval/v1 域：与既有 safe-wallet/tx-batch/v1 直接提交
296	 * 签名互不通用；任一调用的收款方/金额/data 变化，或调用顺序/项数变化，都会改变摘要；
297	 * 版本漂移后旧审批签名自然失效（由引擎按版本拦截）。
298	 */
299	export function hashBatchApproval(req: {
300	  walletId: string;
301	  version: bigint | number;
302	  nonce: bigint | number;
303	  deadline: bigint | number;
304	  calls: readonly {
305	    to: Address;
306	    value: bigint | number;
307	    data: Uint8Array;
308	  }[];
309	}): Buffer {
310	  const encodedCalls = req.calls.map((call) =>
311	    Buffer.concat([
312	      encBytes(hexToBytes(call.to)),
313	      encUint(call.value),
314	      encBytes(call.data),
315	    ]),
316	  );
317	  return digest(TAG_BATCH_APPROVAL, [
318	    encBytes(walletIdBytes(req.walletId)),
319	    encUint(req.version),
320	    encUint(req.nonce),
321	    encUint(deadlineToBigint(req.deadline)),
322	    encList(encodedCalls),
323	  ]);
324	}
