test('版本漂移（conflicted）的审批仍可撤销；撤销后状态为 revoked 而非 conflicted', () => {
  const { wallet, ownerActors } = setup();
  // 登记策略审批
  const newbie = generateKeyPair();
  const approval = wallet.createPolicyApproval({
    version: 1n,
    nonce: 0n,
    deadline: 9000n,
    newOwners: addresses(ownerActors),
    newConfirmations: 2n,
  });
  // 用另一个 nonce 序列先推进：直接提交一笔普通交易（nonce 0），再提交策略变更（nonce 1）使版本漂移
  const txSigs = signTransaction(ownerActors.slice(0, 2), {
    walletId: WALLET,
    nonce: 0n,
    deadline: 9000n,
    to: TO,
    value: 1n,
  });
  wallet.submitTransaction({ nonce: 0n, deadline: 9000n, to: TO, value: 1n }, txSigs);
  // 直接策略变更（nonce 1），改成相同所有者但确认数 1，版本 1 → 2
  const pcInput = {
    version: 1n,
    nonce: 1n,
    deadline: 9000n,
    newOwners: addresses(ownerActors),
    newConfirmations: 1n,
  };
  const pcSigs = signPolicyApproval(ownerActors.slice(0, 2), {
    walletId: WALLET,
    version: 1n,
    nonce: 1n,
    deadline: 9000n,
    newOwners: addresses(ownerActors),
    newConfirmations: 1n,
  });
  // signPolicyApproval 域 ≠ policy-change 域，不能用于直接提交；改用直接策略变更摘要
  const { hashPolicyChange } = await import('../src/encoding.ts');
  const directSigs = ownerActors
    .slice(0, 2)
    .map((k) => signDigestShim(k, hashPolicyChange({ walletId: WALLET, ...pcInput })));
  void pcSigs;
  const task = wallet.proposePolicyChange(pcInput, directSigs);
  wallet.executeTask(task.id);
  assert.equal(wallet.policyVersion, 2n);
  assert.equal(wallet.getPolicyApproval(approval.id).status, 'conflicted');
  assert.equal(wallet.expectedNonce, 2n);

  // 撤销一个版本漂移的审批：撤销 nonce 为当前期望 2，阈值按当前确认数 1
  const revoked = wallet.revokeApproval(
    { approvalId: approval.id, nonce: 2n, deadline: 9000n },
    revokeSigs(ownerActors, approval.digest, { nonce: 2n, count: 1 }),
  );
  assert.equal(revoked.status, 'revoked');
  assert.equal(wallet.expectedNonce, 3n);
  assert.equal(wallet.policyVersion, 2n);
  void newbie;
});

