  const replay = revokeSigs(ownerActors, other.digest, { nonce: 0n, deadline: 1n });
  assert.throws(
    () => wallet.revokeApproval({ approvalId: other.id, nonce: 0n, deadline: 1n }, replay),
    NonceAlreadyUsedError,
  );
});

